svg.script:
(function () {
  'use strict';
  var SVGNS = 'http://www.w3.org/2000/svg';
  var svg = document.getElementById('anfora-svg');
  var colorMarks = document.getElementById('erase-strokes');
  var sketchMarks = document.getElementById('reveal-strokes');
  var cursor = document.getElementById('brush-cursor');
  var cursorRim = document.getElementById('cursor-rim');
  var size = 140;
  var previous = null;
  var active = null;
  var seed = 1;
  var MAX_STEP = 15;
  var WIDTH = 1173;
  var HEIGHT = 1448;

  function random() {
    seed = (1664525 * seed + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  function xy(event) {
    var p = svg.createSVGPoint();
    p.x = event.clientX;
    p.y = event.clientY;
    var mat = svg.getScreenCTM();
    if (!mat) return null;
    return p.matrixTransform(mat.inverse());
  }
  function pathIn(layer, color, width, rough) {
    var el = document.createElementNS(SVGNS, 'path');
    el.setAttribute('fill', 'none');
    el.setAttribute('stroke', color);
    el.setAttribute('stroke-width', width);
    el.setAttribute('stroke-linecap', 'round');
    el.setAttribute('stroke-linejoin', 'round');
    // Keep rounded ends without an SVG filter bounding-box crop.
    // Irregular bristle details are added as separate small strokes below.
    layer.appendChild(el);
    return el;
  }
  function start(x, y) {
    previous = { x: x, y: y };
    var c = pathIn(colorMarks, '#000', size, true);
    var s = pathIn(sketchMarks, '#fff', size, true);
    var d = 'M ' + x.toFixed(2) + ' ' + y.toFixed(2) + ' l 0.02 0.02';
    c.setAttribute('d', d);
    s.setAttribute('d', d);
    active = { c: c, s: s, d: 'M ' + x.toFixed(2) + ' ' + y.toFixed(2), distance: 0 };
  }
  function append(x, y) {
    if (!previous || !active) { start(x, y); return; }
    var dx = x - previous.x;
    var dy = y - previous.y;
    var dist = Math.hypot(dx, dy);
    if (dist < 0.65) return;
    var steps = Math.max(1, Math.ceil(dist / MAX_STEP));
    for (var i = 1; i <= steps; i++) {
      var px = previous.x + dx * i / steps;
      var py = previous.y + dy * i / steps;
      active.d += ' L ' + px.toFixed(1) + ' ' + py.toFixed(1);
    }
    active.c.setAttribute('d', active.d);
    active.s.setAttribute('d', active.d);
    active.distance += dist;
    if (active.distance >= 13) {
      active.distance = active.distance % 13;
      var nx = -dy / dist, ny = dx / dist;
      for (var i = 0; i < 2; i++) {
        var side = (i === 0 ? -1 : 1);
        var edge = side * size * (0.48 + 0.12 * random());
        var sx = x + nx * edge + (random() - 0.5) * 9;
        var sy = y + ny * edge + (random() - 0.5) * 9;
        var len = 6 + 23 * random();
        var tx = sx + dx / dist * len;
        var ty = sy + dy / dist * len;
        var bd = 'M ' + sx.toFixed(1) + ' ' + sy.toFixed(1) + ' L ' + tx.toFixed(1) + ' ' + ty.toFixed(1);
        var w = 1.5 + 5 * random();
        for (var pair of [[colorMarks, '#000'], [sketchMarks, '#fff']]) {
          var b = pathIn(pair[0], pair[1], w, false);
          b.setAttribute('d', bd);
        }
      }
    }
    previous = { x: x, y: y };
  }
  function clearPaint() {
    colorMarks.replaceChildren();
    sketchMarks.replaceChildren();
    previous = null;
    active = null;
  }
  function moveBrush(event) {
    var p = xy(event);
    if (!p) return;
    cursor.setAttribute('transform', 'translate(' + p.x + ' ' + p.y + ')');
    cursor.setAttribute('visibility', 'visible');
    if (p.x >= 0 && p.x <= WIDTH && p.y >= 0 && p.y <= HEIGHT) append(p.x, p.y);
  }
  function leaveBrush() {
    clearPaint();
    cursor.setAttribute('visibility', 'hidden');
  }
  function enterBrush(event) {
    previous = null;
    active = null;
    moveBrush(event);
  }
  cursorRim.setAttribute('r', String(size / 2));
  svg.addEventListener('pointerenter', enterBrush);
  svg.addEventListener('pointermove', moveBrush);
  svg.addEventListener('pointerleave', leaveBrush);
  svg.addEventListener('pointercancel', leaveBrush);
  svg.addEventListener('pointerdown', function (e) {
    if (e.pointerType !== 'mouse') {
      svg.setPointerCapture(e.pointerId);
      moveBrush(e);
    }
  });
  svg.addEventListener('pointerup', function (e) {
    if (e.pointerType !== 'mouse') leaveBrush();
  });
  svg.addEventListener('lostpointercapture', leaveBrush);
})();
